# UI kit sheets D (gear, 5x4) and E (misc, 4x4): the Higgsfield prompts behind docs/art/ui-kit-v1/source/sheet-d.png
# and sheet-e.png (Nano Banana Pro, 2k, 2 credits each). Cut them with tools/crafting-ui/icons.py.
# Usage: powershell -File tools/crafting-ui/gen-kit-sheets.ps1 d|e   (HIGGSFIELD_CMD overrides the CLI path)
if ($env:HIGGSFIELD_CMD) { $hf = $env:HIGGSFIELD_CMD } else { $hf = 'higgsfield' }
$style = 'Hand-painted stylized semi-realistic style with bold dark ink outlines around every object and visible painterly brush texture, warm tropical sunlight from the top left, rich saturated colors, consistent three-quarter view, like premium survival-adventure game UI icons (Sea of Thieves, Raft). Each object is centered in its own equal cell with generous magenta padding; nothing touches or overlaps; no frames, no grid lines, no text, no labels, no numbers, no cast shadows, no glow, no magenta inside the objects.'
$which = $args[0]
if ($which -eq 'd') {
$p = "A 5x4 grid sprite sheet of 20 separate pirate video game equipment icons on a perfectly flat, uniform, solid magenta (#FF00FF) background. $style Items in reading order, row 1: (1) a ship's cutlass sword with a brass basket hilt, diagonal; (2) a short boarding dagger with a leather-wrapped grip, diagonal; (3) a small iron ship anchor used as a hand weapon with a rope-wrapped grip; (4) a pair of crossed wooden flintlock pistols; (5) a pair of crossed elegant dueling flintlock pistols with silver inlays. Row 2: (6) two crossed blunderbusses with flared brass muzzles; (7) a knotted red pirate bandana headscarf; (8) a black tricorn hat; (9) a large captain's hat with gold trim and a white feather; (10) a sleeveless tan canvas vest with laces. Row 3: (11) a navy blue officer's long coat with brass buttons; (12) a chest armor breastplate made of pink and orange coral plates; (13) a pair of short brown leather deck boots; (14) a pair of tall black leather boots with folded cuffs; (15) a pair of light teal boots with small white feather wings at the ankles. Row 4: (16) a gold ring with a round coral gemstone; (17) a white shark tooth pendant on a leather cord; (18) an open cracked brass compass; (19) a tiny rum bottle amulet hanging on a leather cord; (20) a cursed gold doubloon coin with a skull, with faint green tint."
& $hf generate create nano_banana_pro --prompt $p --resolution 2k --aspect_ratio 5:4 --wait --wait-timeout 10m 2>&1
} else {
$p = "A 4x4 grid sprite sheet of 16 separate pirate survival video game item icons on a perfectly flat, uniform, solid magenta (#FF00FF) background. $style Items in reading order, row 1: (1) a lit wooden torch with cloth wrapping and an orange flame, diagonal; (2) a crude wooden spear with a knapped grey stone tip lashed with twine, diagonal; (3) a wooden fishing spear with a three-pronged iron tip, diagonal; (4) a neat coil of brown hemp rope. Row 2: (5) a simple curved wooden bow with a taut string, diagonal; (6) a bundle of five wooden arrows with grey stone tips and white fletching tied together; (7) a small campfire of crossed logs ringed with stones with orange flames; (8) a round glass potion flask filled with red liquid and a cork, tied with twine. Row 3: (9) a small wooden treasure chest with iron bands; (10) an ornate teal sea chest with silver trim and a wave emblem; (11) an ornate golden treasure chest with gems; (12) a brown leather adventurer backpack with straps and buckles. Row 4: (13) a leather tool belt with small pouches and a buckle; (14) a small pile of gold doubloon coins; (15) a rolled old treasure map scroll tied with red string; (16) a closed leather-bound journal book with a feather quill."
& $hf generate create nano_banana_pro --prompt $p --resolution 2k --aspect_ratio 1:1 --wait --wait-timeout 10m 2>&1
}
